In `promote_by_book`, accumulate both `data` and the filtered/capped `cands` list in a dict during the first pass, then reuse them in the status-marking loop.

```python
def promote_by_book(files, kind, max_per_file):
    by_book: dict[str, list[dict]] = {}
    files_data: dict[Path, tuple[dict, list[dict]]] = {}  # fp -> (data, cands_to_mark)
    attempted = 0
    for fp in files:
        try:
            data = json.loads(fp.read_text(encoding="utf-8"))
        except Exception as e:
            print(f"  ✗ {fp.name}: parse error: {e}")
            continue
        cands = data["candidates"]
        if kind:
            cands = [c for c in cands if c.get("kind") == kind]
        cands = [c for c in cands if c.get("status") == "pending"]
        if max_per_file:
            cands = cands[:max_per_file]
        files_data[fp] = (data, cands)   # retain for the marking pass
        for c in cands:
            attempted += 1
            by_book.setdefault(data["book"], []).append(_candidate_to_note(c, data["chapter"]))

    promoted = 0
    books_changed = 0
    for book, notes in sorted(by_book.items()):
        book_path = NOTES_DIR / f"{book}.py"
        if not book_path.is_file():
            print(f"  ⚠ {book}: no notes file ({book}.py) — skipping {len(notes)} candidate(s)")
            continue
        n = batch_insert_notes(book_path, notes, skip_existing=True)
        if n:
            promoted += n
            books_changed += 1
            print(f"  ✓ {book}: {n} inserted ({len(notes)} candidates seen)")

    from scripts.core.notes_io import atomic_write
    for fp, (data, cands_to_mark) in files_data.items():
        if cands_to_mark:
            for c in cands_to_mark:
                c["status"] = "promoted"
            atomic_write(fp, json.dumps(data, indent=2, ensure_ascii=False))

    return attempted, promoted, books_changed
```

This removes the second `fp.read_text` call entirely. The `cands_to_mark` list holds references to the same dicts already inside `data["candidates"]`, so mutating `c["status"]` in-place is reflected when `data` is serialized — no logic change needed.
